package com.acme.gateway;

import javax.ws.rs.*;
import javax.ws.rs.core.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;

@Path("/api/v2")
public class TemplateRenderService {

    private static final String HMAC_ALGO = "HmacSHA256";
    private static final String SERVICE_SECRET = System.getenv("INTER_SERVICE_KEY");
    private static final String TEMPLATE_BASE = "/opt/templates/";
    private static final Map<String, Long> nonceCache = new ConcurrentHashMap<>();

    // Cross-service auth: validates HMAC signature from upstream services
    private boolean validateServiceAuth(String signature, String nonce, String payload) {
        if (signature == null || nonce == null) return false;
        // Replay protection
        long now = System.currentTimeMillis();
        if (nonceCache.containsKey(nonce)) return false;
        nonceCache.put(nonce, now);
        // Evict old nonces
        nonceCache.entrySet().removeIf(e -> now - e.getValue() > 300000);
        try {
            Mac mac = Mac.getInstance(HMAC_ALGO);
            mac.init(new SecretKeySpec(SERVICE_SECRET.getBytes("UTF-8"), HMAC_ALGO));
            byte[] expected = mac.doFinal((nonce + ":" + payload).getBytes("UTF-8"));
            byte[] provided = Base64.getDecoder().decode(signature);
            return MessageDigest.isEqual(expected, provided);
        } catch (Exception e) {
            return false;
        }
    }

    // Sanitize template name to prevent path traversal
    private String sanitizeTemplateName(String name) {
        if (name == null) return null;
        // Remove path separators and null bytes
        String cleaned = name.replace("..", "").replace("/", "").replace("\\", "").replace("\0", "");
        if (!cleaned.endsWith(".tpl")) {
            cleaned = cleaned + ".tpl";
        }
        return cleaned;
    }

    // Process SSI-like directives within template content
    // Only allows safe directives: echo, config
    private String processDirectives(String content, Map<String, String> variables) {
        StringBuilder result = new StringBuilder();
        int pos = 0;
        while (pos < content.length()) {
            int start = content.indexOf("<!--#", pos);
            if (start == -1) {
                result.append(content.substring(pos));
                break;
            }
            result.append(content.substring(pos, start));
            int end = content.indexOf("-->", start);
            if (end == -1) {
                result.append(content.substring(start));
                break;
            }
            String directive = content.substring(start + 5, end).trim();
            result.append(evaluateDirective(directive, variables));
            pos = end + 3;
        }
        return result.toString();
    }

    private String evaluateDirective(String directive, Map<String, String> variables) {
        // Parse directive type and attributes
        String[] parts = directive.split("\\s+", 2);
        String type = parts[0].toLowerCase();
        String attrs = parts.length > 1 ? parts[1] : "";

        switch (type) {
            case "echo":
                return handleEcho(attrs, variables);
            case "config":
                return handleConfig(attrs, variables);
            case "include":
                return handleInclude(attrs, variables);
            default:
                return "[unknown directive]";
        }
    }

    private String handleEcho(String attrs, Map<String, String> variables) {
        String varName = extractAttribute(attrs, "var");
        if (varName != null && variables.containsKey(varName)) {
            return escapeHtml(variables.get(varName));
        }
        return "";
    }

    private String handleConfig(String attrs, Map<String, String> variables) {
        // Config only affects rendering settings, safe
        return "";
    }

    private String handleInclude(String attrs, Map<String, String> variables) {
        String virtualPath = extractAttribute(attrs, "virtual");
        if (virtualPath == null) return "[include error]";
        // Resolve included file relative to template base
        // Apply same sanitization as top-level template
        String resolved = resolveIncludePath(virtualPath, variables);
        if (resolved == null) return "[include denied]";
        try {
            String included = new String(Files.readAllBytes(Paths.get(resolved)), "UTF-8");
            // Recursively process directives in included content
            return processDirectives(included, variables);
        } catch (IOException e) {
            return "[include not found]";
        }
    }

    private String resolveIncludePath(String virtualPath, Map<String, String> variables) {
        // Variable interpolation in include paths for dynamic templates
        String interpolated = interpolateVariables(virtualPath, variables);
        // Security: ensure resolved path stays within template base
        String sanitized = interpolated.replace("..", "").replace("\0", "");
        Path resolved = Paths.get(TEMPLATE_BASE, sanitized).normalize();
        if (!resolved.startsWith(TEMPLATE_BASE)) {
            return null;
        }
        return resolved.toString();
    }

    private String interpolateVariables(String input, Map<String, String> variables) {
        String result = input;
        for (Map.Entry<String, String> entry : variables.entrySet()) {
            result = result.replace("${" + entry.getKey() + "}", entry.getValue());
        }
        return result;
    }

    private String extractAttribute(String attrs, String name) {
        // Parse attribute like: name="value"
        int idx = attrs.indexOf(name + "=\"");
        if (idx == -1) return null;
        int start = idx + name.length() + 2;
        int end = attrs.indexOf('"', start);
        if (end == -1) return null;
        return attrs.substring(start, end);
    }

    private String escapeHtml(String input) {
        return input.replace("&", "&amp;").replace("<", "&lt;")
                    .replace(">", "&gt;").replace("\"", "&quot;");
    }

    @POST
    @Path("/render")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.TEXT_HTML)
    public Response renderTemplate(@HeaderParam("X-Service-Signature") String signature,
                                   @HeaderParam("X-Service-Nonce") String nonce,
                                   Map<String, Object> request) {
        String templateName = (String) request.get("template");
        @SuppressWarnings("unchecked")
        Map<String, String> variables = (Map<String, String>) request.get("variables");

        if (templateName == null || variables == null) {
            return Response.status(400).entity("Missing parameters").build();
        }

        // Validate cross-service authentication
        String payload = templateName + ":" + variables.hashCode();
        if (!validateServiceAuth(signature, nonce, payload)) {
            return Response.status(403).entity("Authentication failed").build();
        }

        String safeName = sanitizeTemplateName(templateName);
        Path templatePath = Paths.get(TEMPLATE_BASE, safeName);

        try {
            String content = new String(Files.readAllBytes(templatePath), "UTF-8");
            String rendered = processDirectives(content, variables);
            return Response.ok(rendered).build();
        } catch (IOException e) {
            return Response.status(404).entity("Template not found").build();
        }
    }
}
